import { getEffectiveRequestHost } from "../../../utils/request-host.js";
import { jsonResponse } from "../http-helpers.js";
export function handleProjectsAPI(req, ctx) {
    const { pathname } = new URL(req.url);
    if (req.method !== "GET" && req.method !== "HEAD")
        return null;
    if (pathname !== "/_projects/api/config")
        return null;
    return handleGetConfig(req, ctx);
}
function handleGetConfig(req, ctx) {
    const url = new URL(req.url);
    const host = getEffectiveRequestHost(req, url) || "localhost";
    const hostWithoutPort = host.replace(/:\d+$/, "") || "localhost";
    const port = host.includes(":") ? host.split(":")[1] ?? "" : "";
    return jsonResponse({
        domain: hostWithoutPort,
        port,
        hasToken: Boolean(ctx.proxyToken || ctx.config?.fs?.veryfront?.apiToken),
    });
}
